                importData() {
                    try {
                        const input = document.createElement("input");
                        input.type = "file";
                        input.accept = ".json";
                        input.onchange = (e) => {
                            const file = e.target.files[0];
                            if (!file) return;
                            const reader = new FileReader();
                            reader.onload = (event) => {
                                try {
                                    const content = event.target.result.toString(),
                                        updateJsonData = JSON.parse(content);
                                    layer.confirm("确定是否要覆盖导入？", {
                                        icon: 3,
                                        title: "确认覆盖",
                                        btn: ["确定", "取消"]
                                    }, (async function (index) {
                                        await storageManager.importData(updateJsonData);
                                        show.ok("数据导入成功");
                                        layer.close(index);
                                        location.reload();
                                    }));
                                } catch (err) {
                                    console.error(err);
                                    show.error("导入失败：文件内容不是有效的JSON格式 " + err);
                                }
                            };
                            reader.onerror = () => {
                                show.error("读取文件时出错");
                            };
                            reader.readAsText(file);
                        };
                        document.body.appendChild(input);
                        input.click();
                        setTimeout((() => document.body.removeChild(input)), 1e3);
                    } catch (err) {
                        console.error(err);
                        show.error("导入数据时出错: " + err.message);
                    }
                }

